SELECT CAST(p / 10000 AS TEXT) AS bucket, CAST(SUM(k) AS TEXT) AS n, encode(sha256(convert_to(string_agg(CAST(p AS TEXT) || ':' || CAST(k AS TEXT) || chr(10), '' ORDER BY p), 'UTF8')), 'hex') AS digest FROM (SELECT person_id AS p, COUNT(*) AS k FROM dsomop_it_636008_9efd21c6_cdm.person WHERE person_id IS NOT NULL GROUP BY person_id) dsomop_membership GROUP BY p / 10000 ORDER BY p / 10000
